function parseField(field, min, max) {
  const items = field.split(',');
  const allowed = new Set();

  for (const item of items) {
    if (item === '*') {
      for (let i = min; i <= max; i++) allowed.add(i);
    } else if (item.includes('/')) {
      const [range, stepStr] = item.split('/');
      const step = parseInt(stepStr, 10);
      if (isNaN(step) || step <= 0) throw new SyntaxError('Invalid step');

      let start, end;
      if (range === '*') {
        start = min;
        end = max;
      } else if (range.includes('-')) {
        const [s, e] = range.split('-');
        start = parseInt(s, 10);
        end = parseInt(e, 10);
        if (isNaN(start) || isNaN(end) || start > end) throw new SyntaxError('Invalid range');
      } else {
        throw new SyntaxError('Single number with step is not allowed');
      }

      if (isNaN(start) || isNaN(end)) throw new SyntaxError('Invalid range');

      for (let i = start; i <= end; i += step) {
        allowed.add(i);
      }
    } else if (item.includes('-')) {
      const [s, e] = item.split('-');
      const start = parseInt(s, 10);
      const end = parseInt(e, 10);
      if (isNaN(start) || isNaN(end) || start > end) throw new SyntaxError('Invalid range');
      for (let i = start; i <= end; i++) allowed.add(i);
    } else {
      const val = parseInt(item, 10);
      if (isNaN(val) || item !== val.toString()) throw new SyntaxError('Invalid value');
      allowed.add(val);
    }
  }

  for (const val of allowed) {
    if (val < min || val > max) throw new SyntaxError('Value out of range');
  }

  return allowed;
}

function cronMatches(expression, date) {
  if (typeof expression !== 'string') throw new TypeError('Expression must be a string');
  if (!(date instanceof Date) || isNaN(date.getTime())) throw new TypeError('Date must be a valid Date object');

  const fields = expression.trim().split(/\s+/);
  if (fields.length !== 5) throw new SyntaxError('Expression must have five fields');

  const [minField, hourField, domField, monthField, dowField] = fields;

  const minSet = parseField(minField, 0, 59);
  const hourSet = parseField(hourField, 0, 23);
  const domSet = parseField(domField, 1, 31);
  const monthSet = parseField(monthField, 1, 12);
  const dowSet = parseField(dowField, 0, 6);

  const min = date.getUTCMinutes();
  const hour = date.getUTCHours();
  const dateVal = date.getUTCDate();
  const month = date.getUTCMonth() + 1;
  const day = date.getUTCDay();

  const minMatches = minSet.has(min);
  const hourMatches = hourSet.has(hour);
  const monthMatches = monthSet.has(month);

  if (!minMatches || !hourMatches || !monthMatches) return false;

  const domStartsWithStar = domField.startsWith('*');
  const dowStartsWithStar = dowField.startsWith('*');

  if (domStartsWithStar || dowStartsWithStar) {
    return domSet.has(dateVal) && dowSet.has(day);
  } else {
    return domSet.has(dateVal) || dowSet.has(day);
  }
}

module.exports = { cronMatches };"}
